def split_painting(segments):
    diff = {}
    for start, end, color in segments:
        diff[start] = diff.get(start, 0) + color        # color begins here
        diff[end] = diff.get(end, 0) - color              # color ends here

    points = sorted(diff.keys())
    result = []
    running = 0
    for i in range(len(points)):
        running += diff[points[i]]
        if i + 1 < len(points) and running > 0:
            result.append([points[i], points[i + 1], running])
    return result

