import java.util.*;

public class Main {
    static List<long[]> splitPainting(int[][] segments) {
        TreeMap<Long, Long> diff = new TreeMap<>();
        for (int[] seg : segments) {
            diff.merge((long) seg[0], (long) seg[2], Long::sum);     // color begins here
            diff.merge((long) seg[1], -(long) seg[2], Long::sum);    // color ends here
        }
        List<Long> points = new ArrayList<>(diff.keySet());
        List<long[]> result = new ArrayList<>();
        long running = 0;
        for (int i = 0; i < points.size(); i++) {
            running += diff.get(points.get(i));
            if (i + 1 < points.size() && running > 0) {
                result.add(new long[]{points.get(i), points.get(i + 1), running});
            }
        }
        return result;
    }
}

