#include <bits/stdc++.h>
using namespace std;

vector<array<long long,3>> splitPainting(vector<array<int,3>>& segments) {
    map<long long, long long> diff;
    for (auto& seg : segments) {
        diff[seg[0]] += seg[2];                            // color begins here
        diff[seg[1]] -= seg[2];                             // color ends here
    }
    vector<long long> points;
    for (auto& [pos, delta] : diff) points.push_back(pos);

    vector<array<long long,3>> result;
    long long running = 0;
    for (size_t i = 0; i < points.size(); i++) {
        running += diff[points[i]];
        if (i + 1 < points.size() && running > 0) {
            result.push_back({points[i], points[i + 1], running});
        }
    }
    return result;
}
